import * as React from 'react';
import { composeRefs } from './compose-refs';
import { render } from '@testing-library/react';

describe('repro infinite loop', () => {
  it('composed ref with a state-changing callback ref should not loop', () => {
    let node: HTMLButtonElement | null = null;
    let setCount: React.Dispatch<React.SetStateAction<number>> | undefined;

    function Inner() {
      return <button ref={composeRefs((n) => (node = n as HTMLButtonElement))}>inner</button>;
    }

    function Outer() {
      const [, force] = React.useState(0);
      setCount = force;
      return <Inner />;
    }

    render(<Outer />);
    // simulate fast typing: force updates
    for (let i = 0; i < 50; i++) {
      setCount!((c) => c + 1);
      act2(() => {});
    }
    expect(node).not.toBeNull();
  });
});

