import * as React from 'react';
import { render } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import { Slot } from './slot';

describe('debug', () => {
  it('logs the ref received by child', () => {
    const calls: string[] = [];
    const slotRef = (n: unknown) => calls.push(`slot:${!!n}`);
    const childRef = (n: unknown) => calls.push(`child:${!!n}`);
    render(
      <Slot ref={slotRef as React.Ref<HTMLElement>}>
        <button ref={childRef as React.Ref<HTMLButtonElement>} type="button">
          hi
        </button>
      </Slot>,
    );
    expect(calls, calls.join(' | ')).toContain('child:true');
  });
});

